INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Teilt ein /64-Präfix die Adresse immer in zwei gleiche Teile?', 2, '[{"text": "Ja", "correct": true, "because": "64 Bits Netzwerk, 64 Bits Interface-ID"}, {"text": "Nein", "correct": false, "because": "Standardaufteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Bits bleiben bei einem /48-Präfix für die Interface-ID?', 3, '[{"text": "80", "correct": true, "because": "128 minus 48"}, {"text": "64", "correct": false, "because": "Für /64 typisch"}, {"text": "48", "correct": false, "because": "Netzwerkanteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Teil einer Adresse definiere ich mit einem /56-Präfix?', 4, '[{"text": "Netzwerkanteil", "correct": true, "because": "56 Bits fürs Netzwerk"}, {"text": "Protokolltyp", "correct": false, "because": "Nicht Präfix-spezifisch"}, {"text": "Hostadresse", "correct": false, "because": "Das ist Interface-ID"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /64 lässt 64 Bits für die Interface-ID. b) /48 ist für Organisationen üblich.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) ist mathematisch, b) ist Standard"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Präfixberechnung?', 5, '[{"text": "Hostanzahl", "correct": true, "because": "Ergibt sich aus Interface-ID"}, {"text": "Netzwerkbits", "correct": false, "because": "Kern der Berechnung"}, {"text": "Gesamtlänge", "correct": false, "because": "128 Bits sind Basis"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein /128-Präfix eine Interface-ID hat?', 2, '[{"text": "Nein", "correct": true, "because": "Volle Adresse, keine Teilung"}, {"text": "Ja", "correct": false, "because": "Kein Platz für Interface-ID"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Präfix wähle ich, wenn ich 64 Bits für die Interface-ID brauche?', 3, '[{"text": "/64", "correct": true, "because": "128 - 64 = 64"}, {"text": "/48", "correct": false, "because": "80 Bits übrig"}, {"text": "/56", "correct": false, "because": "72 Bits übrig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Teile berechne ich bei einem /60-Präfix?', 5, '[{"text": "60 Bits Netzwerk", "correct": true, "because": "Definiert Subnetz"}, {"text": "68 Bits Interface-ID", "correct": true, "because": "128 - 60 = 68"}, {"text": "32 Bits Subnetz", "correct": false, "because": "Falsche Teilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) /64 ist für SLAAC nötig. b) Interface-ID ist immer 64 Bits. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) variiert mit Präfix"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Präfixberechnung?', 4, '[{"text": "Netzwerkanteil", "correct": false, "because": "Kern der Definition"}, {"text": "Gesamtlänge 128 Bits", "correct": false, "because": "Basis der Teilung"}, {"text": "Übertragungsgeschwindigkeit", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Netzwerkanteil bei /48 kleiner als bei /64?', 2, '[{"text": "Nein", "correct": true, "because": "48 Bits > 64 Bits"}, {"text": "Ja", "correct": false, "because": "Falsche Richtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten bestimmen eine Adresse bei /56?', 4, '[{"text": "56 Bits Netzwerk", "correct": true, "because": "Präfix definiert"}, {"text": "72 Bits Interface-ID", "correct": true, "because": "128 - 56 = 72"}, {"text": "128 Bits Netzwerk", "correct": false, "because": "Zu groß"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein /64-Präfix keine Subnetze erlaubt. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Kann weiter unterteilt werden"}, {"text": "Ja", "correct": false, "because": "Flexibel nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Berechnung eines /48-Präfix?', 3, '[{"text": "Netzwerkgrenze", "correct": true, "because": "Definiert Subnetz"}, {"text": "Hostanzahl", "correct": false, "because": "Ergibt sich"}, {"text": "Kürzungsregeln", "correct": false, "because": "Darstellungssache"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /64 teilt gleichmäßig. b) /48 hat mehr Netzwerkbits als /64.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) 64/64, b) 48 < 64"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat ein /64-Präfix?', 5, '[{"text": "SLAAC-Kompatibilität", "correct": true, "because": "64 Bits Interface-ID"}, {"text": "Einfache Teilung", "correct": true, "because": "Hälften klar definiert"}, {"text": "Wenige Subnetze", "correct": false, "because": "Einschränkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Präfixberechnung unwichtig?', 3, '[{"text": "Netzwerkanteil", "correct": false, "because": "Kern der Berechnung"}, {"text": "Interface-ID", "correct": false, "because": "Rest der Adresse"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat ein /128-Präfix einen Netzwerkanteil?', 2, '[{"text": "Nein", "correct": true, "because": "Volle Adresse"}, {"text": "Ja", "correct": false, "because": "Keine Teilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein /48-Präfix mehr Subnetze als /64 erlaubt?', 3, '[{"text": "Ja", "correct": true, "because": "Mehr Bits für Subnetze"}, {"text": "Nein", "correct": false, "because": "Falsche Richtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Präfix wähle ich für einen 80-Bit-Netzwerkanteil?', 4, '[{"text": "/80", "correct": true, "because": "80 Bits Netzwerk, 48 Interface-ID"}, {"text": "/64", "correct": false, "because": "Nur 64 Bits"}, {"text": "/48", "correct": false, "because": "Nur 48 Bits"}]');
